    right:3vw !important;
    width:min(430px,94vw) !important;
    max-height:calc(100dvh - 108px);
  }
}

/* Small phones */
@media (max-width: 480px) {
  nav {
    min-height:88px;
    padding:6px 10px 5px !important;
    column-gap:5px;
  }
  nav .brand-mark {
    height:32px !important;
    max-width:min(41vw,138px) !important;
  }
  nav .nav-search, nav .nav-cart { width:33px !important; height:33px !important; }
  nav .nav-cta { max-width:96px; min-height:32px; font-size:.61rem !important; padding:5px 7px !important; }
  nav .nav-links { gap:18px !important; }
  nav .nav-links a { font-size:.73rem !important; }

  .hero {
    min-height:400px;
  }
  .hero .hero-content { padding:0 4vw; }
  .hero h1 { font-size:clamp(2rem,10.5vw,3.8rem); }
  .hero p { font-size:.78rem; line-height:1.7; }

  section { padding:48px 4vw; }
  .featured-section { padding:18px 4vw 26px; }
  .featured-card { height:214px; }
  .featured-art { height:130px; flex-basis:130px; }
  .featured-name { font-size:.86rem; }
  .featured-price { font-size:.82rem; }
  .featured-buy { min-width:78px; height:34px; font-size:.75rem; }

  .pkg-grid { grid-template-columns:1fr; }
  .pkg-grid .pkg-card { min-height:210px; }

  .cart-panel { right:2.5vw !important; width:95vw !important; }
  .cart-item-info { align-items:flex-start; flex-direction:column; gap:5px; }
  .cart-foot { padding:12px; }
}

/* Very narrow phones: keep everything usable without hiding controls */
@media (max-width: 380px) {
  nav .brand-mark { height:29px !important; max-width:120px !important; }
  nav .nav-search, nav .nav-cart { width:31px !important; height:31px !important; }
  nav .nav-cta { max-width:84px; font-size:.56rem !important; padding:4px 6px !important; }
  nav .nav-links { gap:16px !important; }
  nav .nav-links a { font-size:.68rem !important; }

  .hero { min-height:370px; }
  .hero h1 { font-size:clamp(1.8rem,10vw,3rem); }
  .featured-card { height:208px; }
  .featured-art { height:126px; flex-basis:126px; }
}

/* Landscape phones: use the available width while preventing vertical overflow. */
@media (max-width: 768px) and (orientation: landscape) {
  nav { min-height:82px; }
  nav .nav-links { display:flex !important; }
  .hero { min-height:420px; }
}

/* Respect reduced-motion preferences across devices. */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    scroll-behavior:auto !important;
    animation-duration:.01ms !important;
    animation-iteration-count:1 !important;
    transition-duration:.01ms !important;
  }
}


/* ===== HERO TEXT / DESKTOP CTA POSITION FIX ===== */
/* Keep the existing HTML elements intact, but hide the requested hero copy. */
.hero .eyebrow,
.hero .hero-content > p {
  display:none !important;
}

/* Desktop/laptop: keep the CTA aligned with the hero content instead of centered in the viewport. */
@media (min-width:769px) {
  .hero .hero-content {
    margin-left:11.5% !important;
    margin-right:0 !important;
    text-align:right !important;
  }
  .hero .btn-primary {
    display:block !important;
    width:max-content;
    margin:24px 0 0 auto !important;
  }
}

/* Mobile: keep the CTA usable and aligned within the hero content. */
@media (max-width:768px) {
  .hero .hero-content {
    text-align:center !important;
  }
  .hero .btn-primary {
    display:block !important;
    width:max-content;
    max-width:100%;
    margin:20px auto 0 !important;
  }
}

/* Cart checkout: separate PUBG account details for every purchase */
.cart-recipient-heading{font-weight:800;font-size:.92rem;color:#fff;margin:8px 0 5px}
.cart-recipient-note{margin:0 0 12px;color:#8293a2;font-size:.72rem;line-height:1.8}
.cart-recipient-list{display:grid;gap:10px;margin-bottom:16px}
.cart-recipient-card{padding:13px;border:1px solid rgba(73,103,128,.35);border-radius:12px;background:rgba(7,22,36,.62)}
.cart-recipient-title{font-weight:800;color:#f0d15c;font-size:.78rem;margin-bottom:10px}
.cart-recipient-card .checkout-label{display:block;margin-top:8px}
.cart-recipient-card .checkout-input{width:100%;box-sizing:border-box}
@media (max-width:600px){
  .cart-recipient-card{padding:11px}
  .cart-recipient-note{font-size:.68rem}
}

/* Admin featured-products manager */
.featured-admin-panel{display:grid;gap:14px}
.featured-admin-limit{font-family:'Vazirmatn',sans-serif;color:#f0c94f;font-weight:700}
.featured-admin-selected{display:grid;gap:10px}
.featured-admin-row{display:grid;grid-template-columns:minmax(170px,1fr) 150px auto auto minmax(80px,auto);align-items:center;gap:10px;padding:12px;border:1px solid var(--line);border-radius:10px;background:rgba(6,21,34,.72)}
.featured-admin-row .p-info{display:flex;flex-direction:column;gap:4px;min-width:0}
.featured-admin-row .p-info span{font-size:.76rem;color:var(--fade)}
.featured-admin-row input,.featured-admin-add select{width:100%;height:40px;border:1px solid var(--line);border-radius:8px;background:#07111c;color:#fff;padding:0 10px;font-family:'JetBrains Mono',monospace}
.featured-admin-row button,.featured-admin-add button{height:40px;border:1px solid rgba(210,220,226,.35);border-radius:8px;background:rgba(240,201,79,.08);color:#fff;padding:0 12px;cursor:pointer;font-family:'Vazirmatn',sans-serif}
.featured-admin-row button:hover,.featured-admin-add button:hover{border-color:#f0c94f}
.featured-admin-row button.danger{border-color:rgba(255,80,80,.4);color:#ff9a9a;background:rgba(255,60,60,.06)}
.featured-admin-add{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px}
.featured-admin-add button:disabled{opacity:.45;cursor:not-allowed}
.featured-admin-hint{font-size:.78rem;color:var(--fade);line-height:1.8}
@media (max-width:760px){
  .featured-admin-row{grid-template-columns:1fr 1fr;}
  .featured-admin-row .p-info{grid-column:1/-1}
  .featured-admin-row .price-save-msg{grid-column:1/-1}
  .featured-admin-add{grid-template-columns:1fr}
}
